def gen(rng):
    def fmt(n, k, edges):
        perm = list(range(n))
        rng.shuffle(perm)
        es = [(perm[a], perm[b]) if rng.random() < 0.5 else (perm[b], perm[a]) for a, b in edges]
        rng.shuffle(es)
        return f'{n} {k}\n' + '\n'.join(f'{a} {b}' for a, b in es)
    def rand_edges(n, mode):
        es = []
        for i in range(1, n):
            if mode == 'path':
                p = i - 1
            elif mode == 'star':
                p = 0
            elif mode == 'cat':
                p = i - 1 if i % 2 == 1 else max(0, i - 2)
            elif mode == 'deep':
                p = rng.randint(max(0, i - 3), i - 1)
            else:
                p = rng.randint(0, i - 1)
            es.append((p, i))
        return es
    tests = [fmt(1, 0, []), fmt(2, 1, [(0, 1)]), fmt(2, 0, [(0, 1)]), fmt(7, 2, rand_edges(7, 'path')),
             fmt(6, 1, [(0, 1), (0, 2), (0, 3), (3, 4), (3, 5)]), fmt(4, 3, rand_edges(4, 'star')), fmt(5, 4, rand_edges(5, 'path')),
             fmt(9, 0, rand_edges(9, 'rand'))]
    for n in (3, 4, 5, 6, 7, 8, 9):
        for mode in ('path', 'star', 'cat', 'deep', 'rand'):
            k = rng.randint(0, n - 1)
            tests.append(fmt(n, k, rand_edges(n, mode)))
    N = 800
    for mode, k in (('path', 200), ('path', 0), ('star', 400), ('cat', 300), ('deep', 400), ('rand', 250), ('rand', 700), ('deep', 100)):
        tests.append(fmt(N, k, rand_edges(N, mode)))
    return tests
